precision highp float;
uniform sampler2D history;
uniform sampler2D mask;
uniform float opacity;
varying vec2 vUv;
void main() {
  gl_FragColor = vec4(
    texture2D(history, vUv).rgb,
    texture2D(mask, vec2(vUv.x, 1.0 - vUv.y)).a * opacity
  );
}

